// Function to strip HTML and return clean plain text
function htmlToPlainText(html) {
  if (!html) return '';
  return html
    // Remove script and style tags completely
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')

    // Replace <br> and </p> with line breaks
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')

    // Remove all remaining HTML tags
    .replace(/<[^>]+>/g, '')

    // Decode common HTML entities
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")

    // Clean up spacing
    .replace(/\n\s*\n/g, '\n\n')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

// Loop over all input items
const items = $input.all();

for (const item of items) {
  // Grab the AI's HTML output. Depending on the model node, it's usually in 'text', 'message.content', or 'output'.
  // Adjust this variable if your AI outputs to a different field name.
  const html = item.json.text || item.json.message?.content || item.json.output || item.json.data || '';

  const plainText = htmlToPlainText(html);

  // Save the cleaned version to a new variable
  item.json.plainTextEmail = plainText;
}

return items;

// Create an empty array to hold our genuine, verified leads
const validLeads = [];

// Loop through all incoming webhook data
for (const item of $input.all()) {

  // Extract the submitted data (handling potential nested 'body' objects)
  const data = item.json.body || item.json;

  const firstName = data.firstName || "";
  const phone = data.phone || "";
  const email = data.email || "";

  // -------------------------------------------------------------
  // 1. ANTI-SPAM: Check for spoof links / URLs in the First Name
  // -------------------------------------------------------------
  // Bots often try to drop website links in the name field.
  const urlRegex = /(http|https|www\.|[a-zA-Z0-9\-\.]+\.[a-zA-Z]{2,3}(\/\S*)?)/i;
  if (urlRegex.test(firstName)) {
      continue; // Skips this lead (drops it)
  }

  // -------------------------------------------------------------
  // 2. EMAIL VALIDATION: Check for a genuine email format
  // -------------------------------------------------------------
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
      continue; // Skips this lead if the email is incorrectly formatted
  }

  // -------------------------------------------------------------
  // 3. PHONE VALIDATION: Ensure it is a valid phone number length
  // -------------------------------------------------------------
  // This strips out all formatting (parentheses, dashes, spaces) 
  // and counts just the digits. Standard US/Local numbers are 10 digits.
  const digitCount = phone.replace(/\D/g, '').length;
  if (digitCount < 10 || digitCount > 15) {
      continue; // Skips this lead if the number is too short or too long
  }

  // If the lead passes all the checks above, it is genuine!
  // We add it to our validLeads array to pass to the OpenAI node.
  validLeads.push(item);
}

// Output only the genuine leads
return validLeads;
